export interface InteractionCallbacks {
    onPointerDown?: (e: PointerEvent, hit: RaycastHit) => void;
    onPointerUp?: (e: PointerEvent, hit: RaycastHit) => void;
    onPointerMove?: (e: PointerEvent, hit: RaycastHit) => void;
    onPointerEnter?: (e: PointerEvent, hit: RaycastHit) => void;
    onPointerLeave?: (e: PointerEvent) => void;
    onClick?: (e: PointerEvent, hit: RaycastHit) => void;
    onDoubleClick?: (e: PointerEvent, hit: RaycastHit) => void;
    onDragStart?: (e: PointerEvent, startPos: Vec3) => void;
    onDrag?: (e: PointerEvent, currentPos: Vec3, delta: Vec3) => void;
    onDragEnd?: (e: PointerEvent, finalPos: Vec3) => void;
}

import { Scene, Circle, Color, InteractionComponent, Vec3 } from "retiam";

const scene = new Scene({ canvas });
const dot = new Circle(1.5, { fill: Color.CYAN });

const interaction = new InteractionComponent({
    draggable: true,
    cursor: "grab",
    onPointerEnter: () => {
        dot.paint.fill = Color.MAGENTA;
    },
    onPointerLeave: () => {
        dot.paint.fill = Color.CYAN;
    },
    onDragStart: () => {
        dot.paint.stroke = Color.WHITE;
        dot.paint.stroke_width = 0.1;
    },
    onDrag: (_e, currentPos) => {
        dot.transform.position = currentPos;
    },
    onDragEnd: () => {
        dot.paint.stroke_width = 0;
    }
});

dot.addComponent(interaction);
scene.add(dot);
